'use strict';

/**
* Evaluate \\( \operatorname{log1pmxf}(x) = \lnf(1+x) - x \\) for a single-precision floating point number.
*
* @module @stdlib/math/base/special/log1pmxf
*
* @example
* var log1pmxf = require( '@stdlib/math/base/special/log1pmxf' );
*
* var v = log1pmxf( 1.1 );
* // returns ~-0.358
*
* v = log1pmxf( 0.99 );
* // returns ~-0.302
*
* v = log1pmxf( -0.99 );
* // returns ~-3.615
*
* v = log1pmxf( NaN );
* // returns NaN
*/

// MODULES //

var log1pmxf= require( './main.js' );


// EXPORTS //

module.exports = log1pmxf;
